#include "title_screen.hpp"
#include "choice_screen.hpp"
extern "C" {
#include "font.h"
}
#include <png.h>
#include <algorithm>
#include <iostream>
void write(const std::string&path,const qlie::Bytes&pixels){png_image im{};im.version=PNG_IMAGE_VERSION;im.width=1280;im.height=720;im.format=PNG_FORMAT_BGRA;if(!png_image_write_to_file(&im,path.c_str(),0,pixels.data(),0,nullptr))throw std::runtime_error("PNG export");}
int main(int argc,char**argv){KFont*font=nullptr;try{if(argc<2)return 2;qlie::Assets assets(argv[1]);whj2::TitleScreen title(assets);title.reset();if(title.ready()||title.confirm()!=whj2::TitleScreen::None||title.ready())throw std::runtime_error("Title intro click consumption");title.update(500);if(!title.ready()||title.select(2)||title.move(1)!=1||title.move(1)!=3||title.hit(1080,590)!=4)throw std::runtime_error("Title layout or locked extra");title.select(4);if(title.confirm()!=whj2::TitleScreen::Quit)throw std::runtime_error("Title quit action");qlie::Bytes normal(1280*720*4);title.draw(normal);if(normal[(10*1280+1270)*4]+normal[(10*1280+1270)*4+1]+normal[(10*1280+1270)*4+2]<80)throw std::runtime_error("Original sky model missing");title.reset(true);title.update(5500);qlie::Bytes alt(normal.size());title.draw(alt);if(normal==alt)throw std::runtime_error("Alternate original background");title.reset(false,true);title.update(5500);if(!title.select(2)||title.confirm()!=whj2::TitleScreen::Extra)throw std::runtime_error("Unlocked extra model");
 whj2::SceneImages hit(assets);hit.command("^ui_hit,file:script/title/button.b,x:500,y:300,scalex:200,scaley:200,rotz:90,motion:*OffMouse");if(!hit.uiHit("ui_hit",500,450)||hit.uiHit("ui_hit",500,470)||hit.uiHit("ui_hit",550,300))throw std::runtime_error("Authored hit transformed rectangle");hit.command("^ui_hit,show:false");if(hit.uiHit("ui_hit",500,300))throw std::runtime_error("Hidden collision rectangle active");
 font=kfont_open(nullptr,0);if(!font)throw std::runtime_error("Font");whj2::ChoiceScreen choice(assets);choice.show({"選択肢一","選択肢二"},font);if(choice.hit(640,260)!=-1)throw std::runtime_error("Choice accepted during entrance");choice.update(250);if(choice.hit(640,260)!=0||choice.hit(640,320)!=1||choice.hit(0,0)!=-1)throw std::runtime_error("Original centered choice layout");qlie::Bytes selected(normal.size());choice.draw(selected);if(std::none_of(selected.begin(),selected.end(),[](uint8_t v){return v!=0;}))throw std::runtime_error("Choice frame/text empty");choice.select(1);choice.update(250);if(argc>2){write(std::string(argv[2])+"/title.png",normal);write(std::string(argv[2])+"/alternate-title.png",alt);write(std::string(argv[2])+"/choice.png",selected);}kfont_close(font);std::cout<<"PASS original title intro, button layout, extra gating and distinct variant output; choice texture/coordinates/entrance gate. Background completeness is not asserted.\n";return 0;}catch(const std::exception&e){if(font)kfont_close(font);std::cerr<<"FAIL "<<e.what()<<"\n";return 1;}}
